-- Lodge De Eik krijgt dezelfde feitenbalk en kamerindeling als De Heide.
--
-- De eigenaar bevestigde op 22 september 2026 dat de indeling van beide lodges
-- exact gelijk is: 4 personen, 2 slaapkamers, 1 badkamer, 60 m².
--
-- Twee dingen stonden daardoor scheef:
--
-- 1. De feitenbalk van De Eik gebruikte andere labels ("Voor :: Maximaal 4
--    personen" in plaats van "Personen :: Maximaal 4"). De schema-generator
--    zoekt op het label, herkende die niet, en liet floorSize,
--    numberOfBedrooms, numberOfBathroomsTotal en occupancy dus weg. De Eik
--    had daarmee een magerder schema dan De Heide zonder dat daar een
--    inhoudelijke reden voor was.
--
-- 2. De kamerindeling ontbrak helemaal op /lodge-de-eik, terwijl /lodge-de-heide
--    hem wel had. Diezelfde kaarten staan er nu, met dezelfde picto's.
--
-- Let op de toelichting onder de kaarten: die zegt erbij dat het grondvlak
-- gelijk is en dat de ruimte van De Eik in de hoogte zit. Zonder die zin zou
-- de identieke 60 m² lijken te botsen met wat de pagina verderop zegt --
-- dat De Eik de ruimste van de twee is.
--
-- Idempotent: een tweede run zet dezelfde waarden terug.

update landing_pages
   set key_facts = 'Personen :: Maximaal 4
Slaapkamers :: 2
Badkamer :: 1
Oppervlakte :: 60 m²
Wellness :: Eigen buitensauna én hottub
Buiten :: Buitenkeuken met BBQ
Verblijf :: Weekend, midweek of week',
       sections = '[{"heading": "Wat er in de lodge zit", "body": ["De Eik is de ruimste van de twee. Dat merkt u vooral aan de hoogte: het is een omgebouwd gebouw met hoge plafonds, en dat maakt een verblijf met vier mensen aanzienlijk minder krap dan de vierkante meters doen vermoeden."], "bullets": ["Ruimte voor maximaal vier personen, verdeeld over twee slaapplekken.", "Volledig uitgeruste binnenkeuken: oven, kookplaat, koelkast, vaatwasser, servies en pannen.", "Buitenkeuken met BBQ onder de eiken, met de eettafel op hetzelfde terras.", "Eigen barrelsauna in de tuin, te stoken wanneer u wilt — geen reservering, geen tijdslot.", "Privé-hottub op het terras, het hele jaar door op 38 °C.", "Gratis snel WiFi en gratis parkeren op eigen terrein. Er is een laadstation aanwezig bij de lodge; het laden zelf is niet inbegrepen.", "Digitale sloten: inchecken kan tot middernacht zonder dat iemand op u wacht."]}, {"heading": "Kamerindeling", "body": ["De indeling is gelijk aan die van De Heide: twee slaapkamers, elk met een eigen opzet, en een woonkamer waar met z''n vieren aan tafel gegeten kan worden."], "cards": [{"titel": "Slaapkamer 1", "items": [{"icon": "bed", "tekst": "2-persoons bed 1×"}]}, {"titel": "Slaapkamer 2", "items": [{"icon": "bed", "tekst": "1-persoons bed 2×"}]}, {"titel": "Badkamer", "items": [{"icon": "douche", "tekst": "Douche 1×"}, {"icon": "toilet", "tekst": "Toilet 1×"}]}, {"titel": "Woonkamer", "items": [{"icon": "tafel", "tekst": "Eettafel met stoelen"}, {"icon": "tv", "tekst": "TV 1×"}]}, {"titel": "Keuken", "items": [{"icon": "vaatwasser", "tekst": "Afwasmachine 1×"}, {"icon": "koelkast", "tekst": "Koelkast 1×"}, {"icon": "magnetron", "tekst": "Combimagnetron 1×"}, {"icon": "fornuis", "tekst": "Fornuis 1×"}]}], "note": "De lodge is 60 m² en biedt plaats aan maximaal vier personen. Het grondvlak is gelijk aan dat van De Heide; de ruimte zit hier in de hoogte."}, {"eyebrow": "Voorzieningen", "heading": "Wat er verder aanwezig is", "body": ["De voorzieningen waar gasten het vaakst naar vragen, hier op een rij. Ze zijn in beide lodges gelijk — het verschil tussen De Heide en De Eik zit in het uitzicht en de buitensauna, niet in wat er binnen staat."], "marksKaart": true, "marks": [{"icon": "wifi", "tekst": "Gratis snel WiFi"}, {"icon": "tv", "tekst": "Televisie"}, {"icon": "parkeren", "tekst": "Parkeren op eigen terrein"}, {"icon": "koelkast", "tekst": "Koelkast"}, {"icon": "koffie", "tekst": "Koffieapparaat"}, {"icon": "waterkoker", "tekst": "Waterkoker"}, {"icon": "verwarming", "tekst": "Verwarming"}]}, {"eyebrow": "Het onderscheid", "heading": "De buitenkeuken en de BBQ", "body": ["Buiten koken is iets anders dan een BBQ op het gras zetten. Hier staat een echte buitenkeuken: werkblad, BBQ en de ruimte om alles klaar te maken zonder tien keer naar binnen te lopen. Dat verandert hoe een avond verloopt — u staat niet om beurten binnen te koken terwijl de rest buiten zit, u bent er gewoon allemaal.", "De eiken erboven doen de rest. Ze houden de middagzon eruit, waardoor het terras ook in juli bruikbaar blijft, en ze maken het geluid zachter dan u van een terras gewend bent. Als het eten op is, staat de hottub op twee meter.", "En dan is er de barrelsauna. Die staat buiten, in de tuin naast het terras, en is alleen van de gasten van deze lodge. Geen reservering, geen tijdslot, geen mede-gasten — er is op het terrein geen gedeelde wellnessruimte. Van de sauna naar de hottub is tien stappen, en juist in de winter is dat het rondje waar gasten achteraf over vertellen. Wat hier niet staat is het vergezicht: [vergelijk met De Heide](/lodge-de-heide) als vrij uitzicht voor u zwaarder weegt."]}, {"eyebrow": "Voor wie", "heading": "Voor wie deze lodge is", "body": ["De Eik is de lodge voor gezelschappen die samen willen eten. Twee stellen die om beurten koken, een gezin met kinderen die de hele dag buiten zijn, of vier vrienden die vooral een lange tafel en een BBQ nodig hebben.", "Ook met z''n tweeën werkt hij, en dan vooral in het voor- en naseizoen: de ruimte is dan luxe in plaats van overmaat, en de sauna komt juist dan het best tot zijn recht. Zoekt u vooral stilte en een vrij vergezicht, dan is De Heide de betere keuze."]}, {"eyebrow": "De ligging", "heading": "Onder de eiken in Zeijen", "body": ["Zeijen is een van de brinkdorpen van Drenthe: een kerk, een brink, en daaromheen vrijwel meteen het veld. De lodge staat aan de rand daarvan, met de eiken eromheen en de Zeijerstrubben op loopafstand. Het centrum van Assen ligt op twintig minuten, wat ver genoeg is om er ''s avonds niets van te merken.", "Vanaf de deur beginnen de wandelroutes; er lopen meer dan 1.000 kilometer fietspaden door de omgeving en de e-bike laadt u op aan een buitenstopcontact bij de lodge. Wie hier komt voor de streek zelf, vindt de routes op onze pagina''s over [wandelroutes in Drenthe](/wandelroutes-drenthe) en [fietsen in Drenthe](/fietsen-in-drenthe)."]}, {"eyebrow": "Praktisch", "heading": "Prijzen en beschikbaarheid", "body": ["De prijs begint bij €165 per nacht voor de hele lodge, niet per persoon. In de schoolvakanties, rond feestdagen en in het hoogseizoen ligt hij hoger. Kosten voor eindschoonmaak en toeristenbelasting worden apart vermeld en komen bij de dagprijs. Boekingskosten rekenen wij niet, omdat u rechtstreeks bij de eigenaar boekt.", "Losse nachten verhuren wij niet. Er zijn twee wisseldagen — maandag en vrijdag — en daarmee drie vormen:"], "table": {"head": ["Vorm", "Aankomst", "Vertrek", "Nachten"], "rows": [["Weekend", "Vrijdag", "Zondag", "2"], ["Midweek", "Maandag", "Vrijdag", "4"], ["Week", "Maandag", "Zondag", "6"]], "note": "U geeft uw datums door en krijgt binnen 24 uur een persoonlijk voorstel met de volledige prijsopbouw: nachtprijs, schoonmaak en toeristenbelasting als aparte regels."}}, {"heading": "Praktische informatie", "body": [], "rows": [{"label": "Geschikt voor", "waarde": "1 – 4 personen"}, {"label": "Verhuurperiodes", "waarde": "Midweek (ma – vr), weekend (vr – zo) of week (ma – zo)"}, {"label": "Inchecken", "waarde": "Van 15:00 tot 21:00"}, {"label": "Uitchecken", "waarde": "Uiterlijk 11:00"}], "note": "Later aankomen dan 21:00 kan zonder extra kosten: de lodge heeft digitale sloten die tot middernacht werken, en er is geen receptie waar u zich hoeft te melden."}, {"heading": "Huisregels", "body": [], "marks": [{"icon": "nietRoken", "tekst": "Niet roken binnen"}, {"icon": "huisdier", "tekst": "Huisdieren toegestaan (€25)"}, {"icon": "geenFeest", "tekst": "Geen feesten of evenementen"}], "subheading": "Aanvullende huisregels", "dots": ["Tussen 22:00 en 08:00 uur geldt de nachtrust.", "Roken mag buiten, op de daarvoor bestemde plek.", "Alleen de directe omgeving van deze accommodatie is vuurwerkvrij."]}, {"heading": "Annuleren", "body": ["De volledige voorwaarden staan in de [algemene voorwaarden](/terms); dit is de samenvatting die er voor uw boeking toe doet."], "bullets": ["Tot 60 dagen voor aankomst krijgt u alles terug, op €25 administratiekosten na.", "Tussen 60 en 30 dagen voor aankomst 70%, tussen 30 en 14 dagen 50% en tussen 14 en 7 dagen 25%.", "Binnen 7 dagen voor aankomst is er geen restitutie.", "Omboeken kan tot 30 dagen voor aankomst, na goedkeuring en afhankelijk van beschikbaarheid. Daarvoor geldt een wijzigingsvergoeding van €25."]}, {"eyebrow": "De keuze", "heading": "De Eik of De Heide?", "body": ["Kort: De Eik heeft de buitensauna, de buitenkeuken en de ruimte, De Heide het panoramisch uitzicht. Verder zijn ze gelijkwaardig — beide voor vier personen, beide met een eigen hottub, beide volledig privé en op hetzelfde terrein.", "Weet u het nog niet, kies dan op wat u ''s avonds wilt doen. Buiten eten met de BBQ aan en daarna de sauna in: De Eik. Rustig naar de heide kijken met het water op 38 °C: De Heide."]}]'::jsonb,
       updated_at = now()
 where slug = 'lodge-de-eik';

-- ── Controle na afloop ────────────────────────────────────────────────────
-- Hoort 1 rij te geven, met overal true:
--
--   select slug,
--          key_facts like '%Personen :: Maximaal 4%'   as personen_ok,
--          key_facts like '%Oppervlakte :: 60 m²%'       as oppervlak_ok,
--          sections::text like '%Kamerindeling%'       as indeling_ok
--     from landing_pages
--    where slug = 'lodge-de-eik';
